18	
19	// ============================================================
20	// Protected layout — redirects to /login if not authenticated
21	// ============================================================
22	
23	function ProtectedLayout() {
24	  const { token, isLoading } = useAuth();
25	
26	  if (isLoading) {
27	    return (
28	      <div className="flex min-h-screen items-center justify-center">
29	        <p className="text-muted-foreground">Loading…</p>
30	      </div>
31	    );
32	  }
33	
34	  if (!token) {
35	    return <Navigate to="/login" replace />;
36	  }
37	
38	  return <AppShell />;
39	}
40	
41	// ============================================================
42	// Router
43	// ============================================================
44	
45	const router = createBrowserRouter([
46	  {
47	    path: '/login',
48	    element: <LoginPage />,
49	  },
50	  {
51	    path: '/auth/callback',
52	    element: <AuthCallbackPage />,
53	  },
54	  {
55	    element: <ProtectedLayout />,
56	    children: [
57	      {
58	        index: true,
59	        element: <Navigate to="/dashboard" replace />,
60	      },
61	      {
62	        path: '/dashboard',
63	        element: <DashboardPage />,
64	      },
65	      {
66	        path: '/analytics',
67	        element: <AnalyticsPage />,
68	      },
69	      {
70	        path: '/trades',
71	        element: <TradesPage />,
72	      },
73	      {
74	        path: '/trades/new',
75	        element: <NewTradePage />,
76	      },
77	      {
78	        path: '/trades/:id',
79	        element: <TradeDetailPage />,
80	      },
81	      {
82	        path: '/coach',
83	        element: <CoachPage />,
84	      },
85	      {
86	        path: '/coach/setup',
87	        element: <CoachSetupPage />,
88	      },
89	      {
90	        path: '/prop-shield',
91	        element: <PropShieldPage />,
92	      },
93	      {
94	        path: '/prop-shield/new',
95	        element: <PropShieldNewPage />,
96	      },
97	      {
98	        path: '/prop-shield/:id',
99	        element: <PropShieldDetailPage />,
100	      },
101	      {
102	        path: '/settings',
103	        element: <Navigate to="/settings/broker" replace />,
104	      },
105	      {
106	        path: '/settings/broker',
107	        element: <BrokerSettingsPage />,
108	      },
109	      {
110	        path: '/settings/billing',
111	        element: <BillingSettingsPage />,
112	      },
113	    ],
114	  },
115	]);
116	
117	export function App() {
118	  return <RouterProvider router={router} />;
119	}
