14	function TodayBehaviorBanner() {
15	  const today = format(new Date(), 'yyyy-MM-dd');
16	  const { data } = useBehaviorMetrics(today, today);
17	
18	  if (!data || data.trade_count === 0) return null;
19	
20	  const alerts: string[] = [];
21	  if (data.tilt.score >= 60) alerts.push(`Tilt ${data.tilt.score}/100`);
22	  if (data.tilt.consecutive_losses >= 3) alerts.push(`${data.tilt.consecutive_losses} consecutive losses`);
23	  if (data.revenge_trades.length > 0) alerts.push(`${data.revenge_trades.length} revenge trade(s)`);
24	  if (data.overtrading.overtrading_days > 0) alerts.push('Overtrading today');
25	
26	  if (alerts.length === 0) {
27	    return (
28	      <div className="flex items-center gap-2 rounded-lg border border-green-300 bg-green-50 px-4 py-2.5 text-sm text-green-800 dark:border-green-800 dark:bg-green-950/30 dark:text-green-300">
29	        <TrendingUp className="h-4 w-4 shrink-0" />
30	        <span>
31	          Clean session so far — {data.trade_count} trade(s), discipline {data.discipline.score}/100
32	        </span>
33	      </div>
34	    );
35	  }
36	
37	  return (
38	    <div className={cn(
39	      'flex items-start gap-2 rounded-lg border px-4 py-2.5 text-sm',
40	      'border-amber-300 bg-amber-50 text-amber-900 dark:border-amber-800 dark:bg-amber-950/30 dark:text-amber-300'
41	    )}>
42	      <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
43	      <div>
44	        <span className="font-medium">Behavior alerts today: </span>
45	        {alerts.join(' · ')}
46	        <Link to="/analytics" className="ml-2 underline underline-offset-2 text-xs">
47	          View details
48	        </Link>
49	      </div>
50	    </div>
51	  );
52	}
