54	export function DashboardPage() {
55	  const summary = useSummary();
56	  const bySetup = useBySetup();
57	  const bySession = useBySession();
58	  const byInstrument = useByInstrument();
59	
60	  const hasNoTrades =
61	    !summary.isLoading && summary.data != null && summary.data.total_trades === 0;
62	
63	  if (hasNoTrades) {
64	    return (
65	      <div className="flex flex-col items-center justify-center gap-4 py-24">
66	        <h1 className="text-2xl font-semibold">Dashboard</h1>
67	        <p className="max-w-sm text-center text-muted-foreground">
68	          Start journaling to see your analytics
69	        </p>
70	        <Button asChild>
71	          <Link to="/trades/new">Log Your First Trade</Link>
72	        </Button>
73	      </div>
74	    );
75	  }
76	
77	  return (
78	    <div className="space-y-6">
79	      <div className="flex items-center justify-between">
80	        <h1 className="text-2xl font-semibold">Dashboard</h1>
81	        <Button variant="outline" size="sm" asChild>
82	          <Link to="/analytics">Full Analytics</Link>
83	        </Button>
84	      </div>
85	
86	      <TodayBehaviorBanner />
87	
88	      <SummaryCards />
89	
90	      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
91	        <BreakdownTable
92	          title="By Setup Type"
93	          rows={bySetup.data ?? []}
94	          labelMap={SETUP_TYPE_LABELS as Record<string, string>}
95	        />
