1	import {
2	  CartesianGrid,
3	  Line,
4	  LineChart,
5	  ResponsiveContainer,
6	  Tooltip,
7	  XAxis,
8	  YAxis,
9	} from 'recharts';
10	import { useEquityCurve } from '@/hooks/use-analytics';
11	import { Skeleton } from '@/components/ui/skeleton';
12	
13	interface Props {
14	  dateStart?: string;
15	  dateEnd?: string;
16	}
17	
18	export function EquityCurve({ dateStart, dateEnd }: Props) {
19	  const { data, isLoading } = useEquityCurve(dateStart, dateEnd);
20	
21	  if (isLoading) return <Skeleton className="h-64 w-full rounded-lg" />;
22	
23	  if (!data || data.length === 0) {
24	    return (
25	      <div className="flex h-64 items-center justify-center rounded-lg border">
26	        <p className="text-sm text-muted-foreground">No closed trades yet</p>
27	      </div>
28	    );
29	  }
30	
31	  const chartData = data.map((p) => ({
32	    date: p.date.slice(5),  // "MM-DD"
33	    r: p.cumulative_r,
34	    pnl: p.cumulative_pnl,
35	  }));
36	
37	  const isPositive = chartData[chartData.length - 1].r >= 0;
38	
39	  return (
40	    <div className="rounded-lg border">
41	      <div className="border-b px-4 py-3">
42	        <h3 className="text-sm font-semibold">Equity Curve (Cumulative R)</h3>
43	      </div>
44	      <div className="p-4">
45	        <ResponsiveContainer width="100%" height={220}>
46	          <LineChart data={chartData} margin={{ top: 4, right: 16, left: 0, bottom: 4 }}>
47	            <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
48	            <XAxis
49	              dataKey="date"
50	              tick={{ fontSize: 11 }}
51	              tickLine={false}
52	              axisLine={false}
53	              interval="preserveStartEnd"
54	            />
55	            <YAxis
56	              tick={{ fontSize: 11 }}
57	              tickLine={false}
58	              axisLine={false}
59	              tickFormatter={(v) => `${v}R`}
60	            />
61	            <Tooltip
62	              content={({ active, payload, label }) => {
63	                if (!active || !payload?.[0]) return null;
64	                const d = payload[0].payload;
65	                return (
66	                  <div className="rounded border bg-background p-2 text-xs shadow-md">
67	                    <p className="font-medium">{label}</p>
68	                    <p>Cumulative R: {d.r.toFixed(2)}R</p>
69	                    {d.pnl != null && <p>Cumulative PnL: ${d.pnl.toLocaleString()}</p>}
70	                  </div>
71	                );
72	              }}
